INSERT INTO `properties` (`property_id`, `landlord_id`, `category`, `title`, `location`, `campus`, `distance`, `base_price`, `recommended_pax`, `price_unit`, `per_head_note`, `availability`, `slots_left`, `rating`, `review_count`, `badges`, `map_url`, `video_tour_url`, `nearby_spots`, `gallery`, `sections`, `contract_info`, `contact_name`, `contact_phone`, `contact_whatsapp`, `status`, `pdpa_consent`) VALUES (1, 2, 'rental', 'Rumah Teres 2 Tingkat Taman Bahtera (Berhadapan Pintu KSAJS)', 'Taman Bahtera', 'KSAJS', '600m jalan kaki ke Kampus Sultan Abdul Jalil Shah (KSAJS)', 1200, 6, 'bulan (Sebuah Rumah / Muat 6 Pelajar)', 'Anggaran RM 200 seorang (Hanya RM 180/seorang dengan Kad Matrik!)', 'Masuk Segera', '1 Buah Rumah Kosong (Sedia Didiami)', 4.95, 32, '[\"Jalan Kaki ke KSAJS\",\"WiFi Unifi 300Mbps\",\"Lengkap Meja Belajar\"]', 'https://www.google.com/maps/search/?api=1&query=Taman+Bahtera+Tanjung+Malim', 'https://www.youtube.com/results?search_query=Taman+Bahtera+Tanjung+Malim+UPSI', '[{\"name\":\"Pintu Masuk Utama UPSI (KSAJS)\",\"dist\":\"5 minit jalan kaki (600m)\"},{\"name\":\"Deretan Kedai Makan Pelajar & Dobi Layan Diri 24 Jam\",\"dist\":\"2 minit jalan kaki (150m)\"},{\"name\":\"Stesen KTM Tanjung Malim\",\"dist\":\"5 minit memandu (2.1km)\"},{\"name\":\"Klinik Kesihatan Tanjung Malim & Farmasi\",\"dist\":\"4 minit memandu (1.5km)\"}]', '[{\"label\":\"Pandangan Hadapan & Parkir\",\"url\":\"https:\\/\\/images.unsplash.com\\/photo-1568605114967-8130f3a36994?auto=format&fit=crop&w=1000&q=80\",\"caption\":\"Porch berpagar penuh, muat 2 buah kereta dan 4 buah motosikal pelajar dengan selamat.\"},{\"label\":\"Ruang Tamu & Santai\",\"url\":\"https:\\/\\/images.unsplash.com\\/photo-1586023492125-27b2c045efd7?auto=format&fit=crop&w=1000&q=80\",\"caption\":\"Ruang tamu luas lengkap dengan sofa, kipas siling laju, langsir penuh dan modem Unifi 300Mbps.\"},{\"label\":\"Bilik Tidur & Ruang Belajar\",\"url\":\"https:\\/\\/images.unsplash.com\\/photo-1595526114035-0d45ed16cfbf?auto=format&fit=crop&w=1000&q=80\",\"caption\":\"Setiap pelajar mendapat katil bujang, tilam tebal 8 inci, almari pakaian berkunci dan meja belajar + kerusi.\"},{\"label\":\"Ruang Dapur & Mesin Basuh\",\"url\":\"https:\\/\\/images.unsplash.com\\/photo-1556911220-bff31c812dba?auto=format&fit=crop&w=1000&q=80\",\"caption\":\"Dapur lengkap dengan peti sejuk 2 pintu, dapur memasak + tong gas, penapis air Coway dan mesin basuh automatik 10kg.\"},{\"label\":\"Bilik Air Bersih\",\"url\":\"https:\\/\\/images.unsplash.com\\/photo-1584622650111-993a426fbf0a?auto=format&fit=crop&w=1000&q=80\",\"caption\":\"3 bilik air dengan pemanas air (water heater) dan tekanan air kuat.\"}]', '[{\"title\":\"Bilik Tidur & Kelengkapan Belajar (4 Bilik)\",\"icon\":\"fa-bed\",\"items\":[\"6 Set Katil Bujang + Tilam Tebal\",\"6 Set Meja Belajar & Kerusi Ergonomik\",\"6 Almari Baju Berkunci Sendiri\",\"Soket Plug Tambahan Setiap Katil\",\"Kipas Siling & Langsir Blackout\"]},{\"title\":\"Dapur & Kemudahan Dobi\",\"icon\":\"fa-kitchen-set\",\"items\":[\"Mesin Basuh Automatik 10kg\",\"Peti Sejuk 2 Pintu Besar\",\"Penapis Air Coway (Sejuk & Panas)\",\"Dapur Gas 2 Tungku & Rak Pinggan\",\"Ampaian Baju Berbumbung di Belakang\"]},{\"title\":\"Internet, Keselamatan & Parkir\",\"icon\":\"fa-wifi\",\"items\":[\"WiFi Unifi 300Mbps (Percuma dalam sewa)\",\"Gril Besi Keselamatan Penuh Satu Rumah\",\"Lampu Sensor Automatik di Porch\",\"Kawasan Kejiranan Pelajar & Keluarga Selamat\"]}]', '{\"duration\":\"Minimum 2 Semester (1 Tahun Akademik \\/ 10–12 Bulan)\",\"deposit\":\"1 Bulan Deposit Sekuriti + RM 200 Deposit Utiliti (Boleh bayar ansur 2 kali)\",\"notice\":\"Notis 2 bulan sebelum tamat tempoh sewaan\",\"rules\":\"Penyewa perempuan Muslimah sahaja. Dilarang merokok & membawa haiwan peliharaan.\"}', 'Encik Razak bin Othman', '+60 12-554 8890', '60125548890', 'Approved', 1);
INSERT INTO `properties` (`property_id`, `landlord_id`, `category`, `title`, `location`, `campus`, `distance`, `base_price`, `recommended_pax`, `price_unit`, `per_head_note`, `availability`, `slots_left`, `rating`, `review_count`, `badges`, `map_url`, `video_tour_url`, `nearby_spots`, `gallery`, `sections`, `contract_info`, `contact_name`, `contact_phone`, `contact_whatsapp`, `status`, `pdpa_consent`) VALUES (2, 3, 'rental', 'Rumah Teres Proton City (Laluan Utama Bas UPSI ke KSAS)', 'Proton City', 'KSAS', '5 minit perjalanan ke Kampus Sultan Azlan Shah (KSAS Proton City)', 950, 5, 'bulan (Muat 5-6 Pelajar)', 'Anggaran RM 190 seorang (Hanya RM 171/seorang untuk Pelajar Sah!)', 'Masuk Segera', 'Kemasukan Semester Baru Sedia Ada', 4.88, 24, '[\"Laluan Bas Shuttle UPSI\",\"Pemandangan Tasik Embayu\",\"Kawasan Tenang\"]', 'https://www.google.com/maps/search/?api=1&query=Proton+City+Tanjung+Malim+Perak', 'https://www.youtube.com/results?search_query=Proton+City+Tanjung+Malim+Sewa', '[{\"name\":\"Perhentian Bas Shuttle UPSI (Jalan Pulai)\",\"dist\":\"1 minit jalan kaki (80m)\"},{\"name\":\"Tasik Embayu Proton City (Taman Rekreasi)\",\"dist\":\"3 minit berjalan kaki\"},{\"name\":\"Kampus Sultan Azlan Shah (KSAS)\",\"dist\":\"5 minit memandu \\/ Bas UPSI\"},{\"name\":\"Pasar Mini Speedmart 99 & Gerai Makan\",\"dist\":\"3 minit berjalan kaki\"}]', '[{\"label\":\"Pandangan Hadapan Rumah\",\"url\":\"https:\\/\\/images.unsplash.com\\/photo-1570129477492-45c003edd2be?auto=format&fit=crop&w=1000&q=80\",\"caption\":\"Kawasan kejiranan elit Proton City yang bersih, aman dan berlatar belakangkan Banjaran Titiwangsa.\"},{\"label\":\"Ruang Tamu & Meja Makan\",\"url\":\"https:\\/\\/images.unsplash.com\\/photo-1600585154340-be6161a56a0c?auto=format&fit=crop&w=1000&q=80\",\"caption\":\"Ruang santai dengan set sofa, TV asas, meja makan 6 kerusi dan pengudaraan sejuk semula jadi.\"},{\"label\":\"Bilik Utama (Master Bedroom)\",\"url\":\"https:\\/\\/images.unsplash.com\\/photo-1616594039964-ae9021a400a0?auto=format&fit=crop&w=1000&q=80\",\"caption\":\"Bilik utama dilengkapi 2 katil bujang, bilik air bersambung dan almari besar.\"},{\"label\":\"Dapur Kering & Basuh\",\"url\":\"https:\\/\\/images.unsplash.com\\/photo-1556912172-45b7abe8b7e1?auto=format&fit=crop&w=1000&q=80\",\"caption\":\"Kabinet dapur bersih, peti ais 2 pintu, cerek elektrik dan mesin basuh automatik.\"}]', '[{\"title\":\"Bilik & Katil (3 Bilik Tidur, 2 Bilik Air)\",\"icon\":\"fa-bed\",\"items\":[\"5 Katil Bujang Berserta Tilam\",\"Almari Baju Setiap Bilik\",\"Kipas Siling Kawalan Jauh\"]},{\"title\":\"Kemudahan Memasak & Dobi\",\"icon\":\"fa-kitchen-set\",\"items\":[\"Dapur Gas + Tong Gas Disediakan\",\"Peti Sejuk Sharp 2 Pintu\",\"Mesin Basuh Toshiba 8.5kg\"]},{\"title\":\"Kemudahan Akses Bas\",\"icon\":\"fa-bus\",\"items\":[\"Berada betul-betul di laluan Bas Percuma UPSI\",\"Jadual ketibaan bas tepat waktu setiap 20 minit\"]}]', '{\"duration\":\"1 Tahun Akademik (Minimum 10 Bulan)\",\"deposit\":\"2 Bulan Deposit Sekuriti + RM 300 Utiliti\",\"notice\":\"Notis 1 bulan sebelum keluar\",\"rules\":\"Terbuka kepada Siswa atau Siswi UPSI yang bertanggungjawab menjaga kebersihan.\"}', 'Puan Salmah binti Idris', '+60 19-332 2114', '60193322114', 'Approved', 1);
INSERT INTO `properties` (`property_id`, `landlord_id`, `category`, `title`, `location`, `campus`, `distance`, `base_price`, `recommended_pax`, `price_unit`, `per_head_note`, `availability`, `slots_left`, `rating`, `review_count`, `badges`, `map_url`, `video_tour_url`, `nearby_spots`, `gallery`, `sections`, `contract_info`, `contact_name`, `contact_phone`, `contact_whatsapp`, `status`, `pdpa_consent`) VALUES (3, 2, 'rental', 'Studio Bilik Persendirian Taman Universiti (Non-Sharing)', 'Taman Universiti', 'KSAJS', '800m ke Pintu Timur KSAJS UPSI', 350, 1, 'bulan (Bilik Sendiri / Single)', 'RM 350 bilik perseorangan (Hanya RM 315 dengan Pengesahan Kad Pelajar!)', 'Masuk Segera', 'Hanya Tinggal 2 Bilik Single Kosong', 4.9, 18, '[\"Bilik Single Privasi\",\"Termasuk Bil Air & Elektrik\",\"Bilik Air Sendiri\"]', 'https://www.google.com/maps/search/?api=1&query=Taman+Universiti+Tanjung+Malim', 'https://www.youtube.com/results?search_query=Taman+Universiti+Tanjung+Malim+UPSI', '[{\"name\":\"Pintu Timur UPSI KSAJS\",\"dist\":\"8 minit jalan kaki (800m)\"},{\"name\":\"Kafe Pelajar Selera Kampung\",\"dist\":\"1 minit jalan kaki (50m)\"},{\"name\":\"Kedai Runcit & Photostat Printing\",\"dist\":\"2 minit jalan kaki (120m)\"}]', '[{\"label\":\"Bilik Tidur Lengkap\",\"url\":\"https:\\/\\/images.unsplash.com\\/photo-1522771739844-6a9f6d5f14af?auto=format&fit=crop&w=1000&q=80\",\"caption\":\"Bilik selesa dengan katil bujang, meja studi besar bertingkat, rak buku dan pendingin hawa (aircond).\"},{\"label\":\"Bilik Air En-Suite\",\"url\":\"https:\\/\\/images.unsplash.com\\/photo-1620626011761-996317b8d101?auto=format&fit=crop&w=1000&q=80\",\"caption\":\"Bilik air peribadi di dalam bilik, lengkap water heater dan cermin vanity.\"}]', '[{\"title\":\"Kelengkapan Peribadi Bilik\",\"icon\":\"fa-door-closed\",\"items\":[\"Pendingin Hawa (Aircond) & Kipas Siling\",\"Katil Bujang Super Single + Tilam Tebal\",\"Meja Belajar Kayu Jati & Lampu Belajar LED\",\"Almari Baju 3 Pintu Cermin\"]},{\"title\":\"Utiliti Termasuk\",\"icon\":\"fa-bolt\",\"items\":[\"Bil Elektrik & Air Dibiayai Tuan Rumah (Cap RM50\\/bulan)\",\"Internet WiFi Jalur Lebar Berkelajuan Tinggi\"]}]', '{\"duration\":\"Fleksibel 1 Semester (6 Bulan) atau 1 Tahun\",\"deposit\":\"1 Bulan Deposit Sahaja\",\"notice\":\"Notis 1 bulan\",\"rules\":\"Sesuai untuk pelajar tahun akhir (FYP) atau pascasiswazah yang memerlukan ketenangan mutlak.\"}', 'Encik Razak bin Othman', '+60 12-554 8890', '60125548890', 'Approved', 1);
INSERT INTO `properties` (`property_id`, `landlord_id`, `category`, `title`, `location`, `campus`, `distance`, `base_price`, `recommended_pax`, `price_unit`, `per_head_note`, `availability`, `slots_left`, `rating`, `review_count`, `badges`, `map_url`, `video_tour_url`, `nearby_spots`, `gallery`, `sections`, `contract_info`, `contact_name`, `contact_phone`, `contact_whatsapp`, `status`, `pdpa_consent`) VALUES (4, 3, 'homestay', 'Pink Blossom Convo Homestay @ Proton City (3 Minit ke Dewan Canselor)', 'Proton City', 'KSAS', '3 minit memandu ke Dewan Tuanku Canselor (Istiadat Konvokesyen UPSI)', 220, 8, 'malam (Sebuah Rumah Lengkap Aircond)', 'Kadar Konvo / Percutian Keluarga UPSI (Diskaun 10% untuk Keluarga Pelajar Sah)', 'Masuk Segera', 'Tempahan Terbuka Musim Konvokesyen & Pendaftaran Pelajar Baru', 4.98, 47, '[\"Paling Dekat Dewan Canselor\",\"Penuh Aircond Semua Bilik\",\"Sesuai Rombongan Konvo\"]', 'https://www.google.com/maps/search/?api=1&query=Dewan+Tuanku+Canselor+UPSI+Proton+City', 'https://www.youtube.com/results?search_query=Dewan+Tuanku+Canselor+UPSI+Proton+City', '[{\"name\":\"Dewan Tuanku Canselor UPSI (Pusat Konvokesyen)\",\"dist\":\"3 minit memandu (1.2km)\"},{\"name\":\"Kompleks Sukan UPSI & Kolam Renang Olimpik\",\"dist\":\"4 minit memandu\"},{\"name\":\"Restoran Nasi Kandar & Kafe Santai Proton City\",\"dist\":\"2 minit jalan kaki\"}]', '[{\"label\":\"Ruang Tamu Mewah & Selesa\",\"url\":\"https:\\/\\/images.unsplash.com\\/photo-1600210492486-724fe5c67fb0?auto=format&fit=crop&w=1000&q=80\",\"caption\":\"Ruang tamu berhawa dingin sepenuhnya, TV Pintar 55 inci Netflix, perabot moden sesuai untuk santai seisi keluarga.\"},{\"label\":\"Master Bedroom dengan Katil King\",\"url\":\"https:\\/\\/images.unsplash.com\\/photo-1590490360182-c33d57733427?auto=format&fit=crop&w=1000&q=80\",\"caption\":\"Katil King saiz hotel 5 bintang, bilik mandi peribadi dan pengering rambut disediakan.\"},{\"label\":\"Bilik Tidur Kedua (Queen + Single)\",\"url\":\"https:\\/\\/images.unsplash.com\\/photo-1560448204-e02f11c3d0e2?auto=format&fit=crop&w=1000&q=80\",\"caption\":\"Muat 3 orang tetamu, ada pendingin hawa dan tuala mandi bersih disediakan.\"},{\"label\":\"Dapur & Meja Makan Keluarga\",\"url\":\"https:\\/\\/images.unsplash.com\\/photo-1556911220-e15b29be8c8f?auto=format&fit=crop&w=1000&q=80\",\"caption\":\"Kelengkapan memasak lengkap pinggan mangkuk, microwave, periuk nasi elektrik dan penapis air Cuckoo.\"}]', '[{\"title\":\"Bilik Penginapan (4 Bilik Berhawa Dingin)\",\"icon\":\"fa-snowflake\",\"items\":[\"1 Katil King, 2 Katil Queen, 2 Katil Bujang (Muat 8-10 orang)\",\"Set Cadar & Tuala Bersih Disteril\",\"Seterika Wap & Papan Seterika (Mudah gosok jubah konvo)\"]},{\"title\":\"Kemudahan Hiburan & Relaks\",\"icon\":\"fa-tv\",\"items\":[\"Smart TV 55 inci + Netflix & YouTube Premium\",\"Ruang parkir berpagar untuk 2 kereta besar\"]}]', '{\"duration\":\"Harian \\/ Hujung Minggu \\/ Mingguan\",\"deposit\":\"Deposit Tempahan RM 100 (Dipulangkan hari daftar keluar)\",\"notice\":\"Daftar masuk 3:00 PM, Daftar keluar 12:00 PM\",\"rules\":\"Keluarga Muslim sahaja. Dilarang sebarang parti liar atau minuman beralkohol.\"}', 'Puan Salmah binti Idris', '+60 19-332 2114', '60193322114', 'Approved', 1);
INSERT INTO `properties` (`property_id`, `landlord_id`, `category`, `title`, `location`, `campus`, `distance`, `base_price`, `recommended_pax`, `price_unit`, `per_head_note`, `availability`, `slots_left`, `rating`, `review_count`, `badges`, `map_url`, `video_tour_url`, `nearby_spots`, `gallery`, `sections`, `contract_info`, `contact_name`, `contact_phone`, `contact_whatsapp`, `status`, `pdpa_consent`) VALUES (5, 2, 'homestay', 'Behrang 2020 Family Homestay & Event Villa (Dekat Tol Behrang)', 'Behrang 2020', 'KSAJS', '8 minit memandu ke KSAJS / 12 minit ke KSAS Proton City', 250, 12, 'malam (Villa Semi-D Lot Tepi Luas)', 'Kawasan Luas untuk Rombongan Keluarga Besar Konvokesyen UPSI', 'Masuk Segera', 'Tempahan Dibuka untuk Hujung Minggu & Musim Pendaftaran', 4.92, 29, '[\"Laman Luas & BBQ Set\",\"Dekat Plaza Tol Behrang\",\"Muat Hingga 12 Orang\"]', 'https://www.google.com/maps/search/?api=1&query=Bandar+Behrang+2020+Perak', 'https://www.youtube.com/results?search_query=Bandar+Behrang+2020+Perak', '[{\"name\":\"Plaza Tol Behrang (Lebuhraya PLUS)\",\"dist\":\"3 minit memandu (1.5km)\"},{\"name\":\"Pasaraya TF Value Mart Behrang\",\"dist\":\"2 minit memandu\"},{\"name\":\"Kampus Induk KSAJS UPSI\",\"dist\":\"8 minit memandu terus melalui Jalan Persekutuan\"}]', '[{\"label\":\"Pandangan Sudut Tepi (Corner Lot)\",\"url\":\"https:\\/\\/images.unsplash.com\\/photo-1512917774080-9991f1c4c750?auto=format&fit=crop&w=1000&q=80\",\"caption\":\"Laman rumput hijau yang luas, gazebo kayu untuk minum petang dan set BBQ batu.\"},{\"label\":\"Ruang Dewan Tamu Utama\",\"url\":\"https:\\/\\/images.unsplash.com\\/photo-1600607687939-ce8a6c25118c?auto=format&fit=crop&w=1000&q=80\",\"caption\":\"Ruang lapang tanpa sekat berhawa dingin dengan 2 set sofa dan pencahayaan hangat.\"}]', '[{\"title\":\"Keluasan & Kapasiti Tetamu\",\"icon\":\"fa-users\",\"items\":[\"4 Bilik Tidur Luas + 3 Bilik Air (Semua bilik ada aircond)\",\"Ruang parkir luas boleh memuatkan 4 buah kereta di dalam kawasan pagar\"]},{\"title\":\"Aktiviti Santai Keluarga\",\"icon\":\"fa-fire-burner\",\"items\":[\"Pit BBQ & Arang Percuma Disediakan\",\"Meja Karom & Permainan Papan untuk Anak-anak\"]}]', '{\"duration\":\"Harian & Pakej Mingguan\",\"deposit\":\"Deposit Keselamatan RM 150\",\"notice\":\"Pembatalan percuma 7 hari sebelum tarikh ketibaan\",\"rules\":\"Patuhi ketenteraman jiran setempat selepas pukul 11:00 malam.\"}', 'Encik Razak bin Othman', '+60 12-554 8890', '60125548890', 'Approved', 1);
INSERT INTO `property_reviews` (`property_id`, `reviewer_name`, `reviewer_role`, `rating`, `comment`, `review_date`) VALUES (1, 'Nurul Izzah binti Kamal', 'Pelajar Ijazah Pendidikan Matematik (Sem 6)', 5, 'Sangat berbaloi duduk di sini 2 semester! Paling best sebab jalan kaki 5 minit je dah sampai pagar KSAJS. Tuan rumah Encik Razak sangat prihatin dan pembersih.', 'September 2024');
INSERT INTO `property_reviews` (`property_id`, `reviewer_name`, `reviewer_role`, `rating`, `comment`, `review_date`) VALUES (1, 'Muhamad Faiz bin Zamri', 'Alumni Fakulti Muzik', 5, 'Internet Unifi memang laju dan stabil waktu nak submit assignment FYP tengah malam. Rumah sejuk walaupun waktu tengah hari.', 'Julai 2024');
INSERT INTO `property_reviews` (`property_id`, `reviewer_name`, `reviewer_role`, `rating`, `comment`, `review_date`) VALUES (2, 'Syakir Zufayri', 'Pelajar Fakulti Sains & Matematik', 5, 'Laluan bas betul-betul depan lorong rumah, senang sangat ulang-alik ke KSAS Proton City. Kejiranan pun tenang untuk belajar.', 'Oktober 2024');
INSERT INTO `property_reviews` (`property_id`, `reviewer_name`, `reviewer_role`, `rating`, `comment`, `review_date`) VALUES (3, 'Amira Sofea', 'Pelajar Pascasiswazah UPSI', 5, 'Bilik single yang tenang dan selesa. Bil api air dah termasuk memang jimat bajet!', 'Ogos 2024');
INSERT INTO `property_reviews` (`property_id`, `reviewer_name`, `reviewer_role`, `rating`, `comment`, `review_date`) VALUES (4, 'Haji Mahmud & Keluarga', 'Tetamu Konvokesyen ke-25 UPSI', 5, 'Sangat puas hati menginap waktu majlis konvo anak. Hanya 3 minit ke Dewan Tuanku Canselor, tak payah risau jem jalan raya.', 'November 2024');
INSERT INTO `property_reviews` (`property_id`, `reviewer_name`, `reviewer_role`, `rating`, `comment`, `review_date`) VALUES (5, 'Cikgu Zulkifli Rahman', 'Rombongan Kursus UPSI', 5, 'Villa sangat luas, kami sekeluarga 10 orang menginap dengan sangat selesa. Anak-anak seronok berBBQ.', 'Disember 2024');
INSERT INTO `roommate_ads` (`ad_id`, `student_id`, `name`, `gender`, `faculty`, `location`, `budget`, `description`, `phone`, `tags`, `status`, `pdpa_consent`) VALUES (101, 4, 'Aina & Syuhada', 'Siswi (Perempuan)', 'Fakulti Bahasa & Komunikasi (FBK) • Sem 3', 'Taman Bahtera', 180, 'Mencari 2 orang rakan bilik perempuan Muslimah yang pembersih, tidak merokok, dan rajin study. Rumah sudah ada WiFi & peti ais, jalan kaki ke KSAJS.', '60198877665', '[\"Pembersih\",\"Tak Merokok\",\"Ada Motor\",\"Jalan Kaki KSAJS\"]', 'Approved', 1);
INSERT INTO `roommate_ads` (`ad_id`, `student_id`, `name`, `gender`, `faculty`, `location`, `budget`, `description`, `phone`, `tags`, `status`, `pdpa_consent`) VALUES (102, 4, 'Danial & Kumpulan FSSK', 'Siswa (Lelaki)', 'Fakulti Sains Sukan & Kejurulatihan • Sem 4', 'Proton City', 170, 'Ada 1 bilik kosong (muat 2 orang) di Proton City laluan bas KSAS. Mencari siswa yang peramah, aktif sukan atau sama fakulti.', '60172233445', '[\"Mesra\",\"Suka Sukan\",\"Dekat Bas KSAS\"]', 'Approved', 1);
INSERT INTO `roommate_ads` (`ad_id`, `student_id`, `name`, `gender`, `faculty`, `location`, `budget`, `description`, `phone`, `tags`, `status`, `pdpa_consent`) VALUES (103, 5, 'Fatin Nadhirah', 'Siswi (Perempuan)', 'Fakulti Muzik & Seni Persembahan • Sem 2', 'Proton City', 250, 'Mencari bilik single atau kongsi 2 orang yang suasana tenang untuk latihan instrumen muzik. Bajet fleksibel.', '60134455667', '[\"Bilik Single\",\"Suasana Tenang\",\"KSAS Proton City\"]', 'Approved', 1);
INSERT INTO `roommate_ads` (`ad_id`, `student_id`, `name`, `gender`, `faculty`, `location`, `budget`, `description`, `phone`, `tags`, `status`, `pdpa_consent`) VALUES (104, 4, 'Amirul & Hafiz', 'Siswa (Lelaki)', 'Fakulti Komputeran & Meta-Teknologi • Sem 5', 'Behrang 2020', 150, 'Mencari 2 orang housemate untuk sewa rumah semi-D di Behrang 2020. Ada kenderaan sendiri, suka coding & gaming di hujung minggu.', '60189911223', '[\"Ada Kereta\",\"WiFi 300Mbps\",\"Bajet Murah\"]', 'Approved', 1);
